"""Stage 3 merge for report 46."""
import json
C = {x["id"]: x for x in json.load(open("Tools/prd_ledger/canonical.json"))}
def ext(cid, text):
    if text not in C[cid]["statement"]: C[cid]["statement"] += text
def add(cid, section, title, statement):
    if cid in C: return
    C[cid] = dict(id=cid, title=title, statement=statement, section=section, cards=[], reports=[], merged_from=[])

add("C260", "dont", "Never argue price in a public review reply, and never ask a reviewer to change their rating",
    "Report 46: 6 reviews (0.28%, mean 1.33, all 2021 or later, five in 2024–26) say a public developer reply was rude or defensive — 'snarky remarks about working for free and making an overpriced app isn't the way to do it'; 'developer takes any criticism with such a nasty attitude'; 'After reading developer's response I am degrading rating to 1 star from 2… 5/5 rating for app but 0/5 for your behaviour' (13298363427) — and 2 say the developer pressed them to change their review ('the developer keeps contacting me to pressure me into changing my review', 11709301622). Every one of these reviews went from 'too expensive' to 'and the developer is hostile', a reputational cost no pricing change recovers, while 53 reviews (mean 4.94) praise the same developer's private support. The report's zero-cost fix: thank, state the free tier and lifetime option factually, never argue value, never ask for a rating change.")
add("C261", "must-have", "A colour palette users can extend — more defaults, a hex picker, softer sets — because colour is the reward surface",
    "Report 46: 'more / custom / softer colours' is the top feature request in every era after 2020 — 59 reviews (2.71%, mean 4.36; 35 at 5★, 15 at 4★): a hex-code picker ('I would love very much to have the option to enter a hex code… I will pay for this feature!!', 9952382181, tracking 21 habits; 11699632553), pastel and neutral palettes, 'more (than 7) default colors', colours for 21 habits, and 'I would totally splurge a buck 99 for a rain themed color pallete' (12101755389); four say long streaks turn colours muddy ('Yellow disappears completely and turns red. Red turns brown. Green turns olive', 13866974245). A palette pack is the only in-app purchase the corpus asks for unprompted; the request sits on the product's differentiator (the colour-saturation grid, 228 reviews at mean 4.86).")

ext("C001", " Report 46: dark mode was paywalled in 2020 and again in June 2024 ('New update moved dark mode behind a paywall. Immediate deletion'); the report's rule 19 — do not gate further existing capabilities, each episode produced immediate 1–2★.")
ext("C002", " Report 46: a 4.332★ written corpus (4.7 aggregate) where monetisation friction (373, 17.13%, mean 2.80) carries 66.4% of all 1–2★ in every era while praise almost never coexists with a low rating (15 of 250) — 'when this product loses a reviewer, it is not because they disliked the grid; it is because they were stopped by the paywall, disagreed with the price, or lost data'.")
ext("C003", " Report 46: the one-time ask (53, 6.99% of 2018–20 reviews) was answered with a $99.99 lifetime in May 2021 and fell to 0.68%, while 'lifetime price too high' rose from nothing to 27 (2.02% of the second half); reviewers converge on $30–70 ('I have never seen someone charge more than $30 for it… happy to pay $30'; 'Would probably buy it lifetime if it was 30 or less'; 'asking for almost $100 for lifetime is GREEDY'; '69.99 and I probably would have paid'; '¥30 elsewhere, ¥328 here — I don't dare buy it in case it disappears'); 16 bought lifetime (mean 4.56: 'now there is a lifetime option, so I bought it straight away'); non-English storefronts ask to own it outright 2.1× more, China 4.5× — the report's E1 is a $49 / $69 lifetime test.")
ext("C004", " Report 46: a subscription priced against 'simple' invites 'simple things should be cheap' — '$4.99 a month is too much to ask for the ability to electronically check a box'; 'essentially a checkbox $30 (a year)'; benchmarked against Spotify, Lightroom, 200 GB iCloud + Office, 1Password, Notion; price objections 163 (7.48%, mean 2.84) spiking with each rise ($12 → $30/yr in 2020: 'Most of the worth it reviews reflect the original pricing'; $7.49 / $29.99 / $99.99 in 2023) and fading to 4 in 2026; payers justify the price by outcome ('$29/year for what this app is giving me in terms of mental health is an absolute steal'), non-payers by comparison.")
ext("C005", " Report 46: 198 competitive-displacement reviews (9.09%, mean 4.92) — 'nearly every habit tracker… all the way back to Chains.cc'; 'so much better than Streaks!!!! It's not even close'; 'habitica but without the stupid game mechanics'; named rivals Streaks, Productive, Fabulous, Done, Habitica, HabitShare, Finch, Momentum, Way of Life, mem:o, TickTick, (Not Boring) Habits, Awesome Habits, Habitty, Onrise, 习惯口袋; departures only to spreadsheets, Reminders, cheaper lifetime trackers ('Awesome Habits is $22.99 for a LIFETIME license'; 'Habit Pocket… buyout is only ¥45') or bundles ('Done app gave me SIX different apps… $25 for the year') — no design competitor, only price competitors.")
ext("C006", " Report 46: simplicity 425 (19.51%, mean 4.87), the top theme and rising every era (16.40% → 21.59%) — 'I don't want to build a new habit of wasting time while tracking habits'; 'I'm really sick of apps with a million features and AI just to convolute things' (Apr 2026); 'A lot of great apps start this way, then they start adding weird features that nobody wants… pls dont do that' — and the same simplicity is the pricing liability ('Simple and overpriced'); rule 16: do not add complexity to justify the price.")
ext("C007", " Report 46 (the unchanged case): a 3-habit cap held from Jan 2019 to the listing in Sep 2026 is the largest negative (180, 8.26%, mean 2.43; 41.0% of one-stars; identical 8.27% vs 8.25% across market groups — 'a global constant of this product'); its count never fell (26 / 32 / 22 / 18 in 2022–25) while prompted volume halved its rate; the counter-offer is modest (29 name 4, 5, 6 or 7 — nobody unlimited) and the free tier cannot fill the product's own 4-row widget; 66 (mean 4.92) defend three on habit-science grounds; 'discovered after setup' is the indefensible version ('you've already spent 20 minutes or more setting it up', 16 votes).")
ext("C009", " Report 46: interactive widgets are free (contested) and rose from 0.81% to 3.98% of praise — 'I barely even open the app'; the widget holds four rows and the free tier three.")
ext("C011", " Report 46: stats praised by 54 (mean 4.91 — 'I exercised 60% of the time, wrote 80% of the time'); richer statistics requested by 11 (4.55).")
ext("C012", " Report 46: a habit × day grid whose squares deepen in colour with each consecutive completion is the product — 228 reviews (10.47%, mean 4.86): 'Because I don't want the gradient to break, I'm motivated to check in every day'; 'Anybody that like seeing a git commit graph will love this app'; 'not ticks to check off but areas that fill with beautiful colours — so I don't feel stressed about not managing something' — praised at a near-constant 9.68–11.62% for eight years.")
ext("C016", " Report 46: skip marks — a half-square and a triangle — with a 'don't skip twice' rule are praised by 41 (mean 4.93: 'no punishment other than a break in the color gradient') and confuse 19 for seven years ('What does the triangle and squares mean?????'; a subscriber who will 'cancel until this is fixed') — a legend reachable from the grid.")
ext("C019", " Report 46: a habit-breaking mode (colour fades when the bad habit is logged) is praised by 42 (mean 4.98) — alcohol, sugar, screen time — though its logic is unclear to some.")
ext("C020", " Report 46: export / backup / print requested by 3 in an app that lost users' history.")
ext("C022", " Report 46: Apple Watch shipped Mar 2021 and the request stopped (3 → 2 → 0 → 0); Watch ↔ phone sync is then a failure surface ('finished goals on the watch won't show up on the phone and vice versa… a deal breaker').")
ext("C025", " Report 46: students and minors ask for a discount ('the only money i get is chore money and i have to wash the windows for it', 5★; a Cambridge scholarship student; 'please offer discount for students'; 'Is there a discount code for lifetime?'); the report's E5 is a student / youth discount; a discount honoured after it expired won a 5★.")
ext("C027", " Report 46: the UI reached 15 languages (Catalan praised by name; Turkish requested with 16 votes in 2020 and praised in Turkish by 2022) but the Learn content, videos and e-mails stayed English — 'all the support is in English, which surprised me because the developer is Spanish. If it were in Spanish, I'd consider subscribing' (ES); Arabic and Russian reviewers ask the same; the report: localise content, Spanish first.")
ext("C029", " Report 46: 13 billing failures (0.60%, mean 2.31) — charged on day one of a 7-day trial (twice), a subscription the app would not recognise ('App does not recognize it and won't let me add more than three habits, even after refreshing… On to the next app'; premium on iPad not on iPhone), a wrong amount (CHF 40.45 for 29.95), four refund requests — vs 2 refund references in report 43's one-time corpus.")
ext("C030", " Report 46: cross-device sync is a paid trigger ('I did upgrade so the data could be shown and updated on my watch') and a failure surface — sync 15 (mean 3.13), Watch and Mac disagreeing with the phone ('I paid a hefty price to sync with all my devices', subscriber 2★).")
ext("C033", " Report 46: entitlement not recognised across devices or after a trial — 4 payers ('App does not recognize it… even after refreshing the subscription with the provided link'; '明明都在pad己開通高級版，Iphone上卻不給用'; one resolved only by refund and re-purchase); the report's #3 fix is one entitlement across iPhone, iPad, Watch, Mac and web with a visible subscription-status screen.")
ext("C034", " Report 46: data loss 24 (1.10%, mean 2.12), doubling across halves and 8 from payers — checked squares, streaks and history silently rewritten ('marks from a couple of days or even a week ago disappear'; 'the results for habit one are somehow already displayed for habit three'; 'suddenly reset and lost all my data. What am I paying $29.99/year for'); all four 2026 cases from the Russian storefront in 23 days — 'for an app whose entire value is an unbroken visual record, silently rewritten history is the highest-severity failure possible'; the fix asked for is a per-habit change history with 'undo last 7 days' and conflict resolution that never deletes a completed mark.")
ext("C035", " Report 46: an account was required 2018–2022 (8 complaints, mean 1.50; the first review in the corpus could not sign up; login failures mean 1.89) and optional by 2024 — the complaint stopped when the requirement did.")
ext("C036", " Report 46: 7 unanswered (mean 1.57; 'sent 3 different email… Not a single reply'), four of them 2024–26 and two paying customers with unresolved data loss or an unrecognised subscription; support praise 53 (4.94) is falling 4.30% → 1.82% as volume grew.")
ext("C037", " Report 46: no Family Sharing — 'for that, €29 a year is too expensive' (DE, 1★); 'too expensive to have 5 subscriptions so my entire family could use the tool'; the report: offer it on annual and lifetime.")
ext("C039", " Report 46: a deleted habit's notification kept firing (the most-voted review in the corpus, 25 votes); reminders not firing 7; finer reminder control (per day, stop once done) requested by 9.")
ext("C040", " Report 46: widgets blank, stale or wrong — 21 (mean 3.33): 'I deleted the Dry January task but the widget still shows it'; 'every day the home-screen widget colour blocks get scrambled'; 'The widget is the heart of the application' (1★ after contact); interactive widgets also record accidental taps ('marks the completion of that day by mistake… Not great for a paid app') — the report: keep it, add a lock / view-only mode.")
ext("C042", " Report 46: neurodivergent and chronically ill users (30, mean 4.83, 23 US, growing 0.54% → 1.70%) name the forgiving skip ('one off day doesn't kill your streak'; 'neutral data instead of a personal failing'), the widget ('if I don't see something I forget it exists') and minimal input ('a simple yes/no input, which is perfect for me and my ADHD because I've quickly become burnt out by decision fatigue on other apps'; 'Literally 3 click options').")
ext("C043", " Report 46: every-N-days, X-per-week without fixed days and monthly schedules are the longest-running functional request (34, mean 4.09, every era Sep 2019 → Jul 2026) — 'a medicine I must use every other day and I can't put it on this app'; a shift worker on trial calling it 'potentially a deal breaker'; 'most of my habit are repeated every 3 days… Apple reminders is WAY more efficient' (churned).")
ext("C044", " Report 46: a web app and Chrome new-tab extension pre-dated the iPhone app and held the early community ('I have it as my default Chrome tab page'; 'I am not allowed my phone at work'), fading 2.15% → 0.23%; the Mac build is criticised as slow.")
ext("C045", " Report 46: folders / habit groups shipped Aug 2025 after 10 requests ('The new habit folder feature is — chef's kiss').")
ext("C048", " Report 46: several completions per day (12) and numeric targets — glasses, steps, pages (9, mean 4.56) — requested.")
ext("C054", " Report 46: an aggressive in-app rating prompt produced 297 reviews (13.64%) in 44 days in May–June 2023 at mean 4.58 vs 4.29 — permitted by Apple, not fake, but it tripled volume with contentless 5★, diluted every later negative rate and 'made the post-2023 corpus less informative per review'; 17 reviews say they are writing only to make it stop.")
ext("C056", " Report 46: 'I'm really sick of apps with a million features and AI just to convolute things' (Apr 2026, 5★).")
ext("C059", " Report 46: each shipped request stops and a praise theme starts — widgets (Sep 2020), Watch (Mar 2021), journal / calendar (Dec 2023), folders (Aug 2025), no-account use (2024), Turkish and Chinese UI; personal support praised by 53 ('reach out to Joan and received a response in less than 30 minutes'; 'Joan helped me add my previous habit data from a different app'), eight ratings raised after contact.")
ext("C061", " Report 46: 'I paid the subscription fee because it's a great app with a developer who obviously cares' (ADHD); 'I bought it to support the developer' — 13 (mean 4.92), 12 of them before July 2023; three free users state their condition ('If it helps me build three habits, I'll come back and pay!').")
ext("C062", " Report 46: the least US-concentrated corpus (33.43%); the payer rate is twice as high in high-spend markets (5.61% vs 2.85%) and highest in the US (6.04%) while the cap objection is identical everywhere; every regional-price complaint is outside the group; Germany loves the product and disputes the model most (price 2.4×, anti-subscription 3.8×), Russia calls the price fair on an apparently lower tier, China wants a buyout and fears the app will vanish (跑路), India negotiates for 4–7 free habits, Turkey is the clearest regional-price market.")
ext("C063", " Report 46: a 7-day trial is the top purchase trigger ('I paid for the full version after the trial because I could see how much it had helped in just a week'; 'Absolutely did not hesitate to purchase after the week trial'; 'used this app for 6 days and fully expected to delete it… I will be subscribing') — yet 32 (mean 1.88) say the 3-habit free tier is too small to evaluate ('I'd have to subscribe before even trying it'; 'try it for 30 days without limitation').")
ext("C064", " Report 46: $12/year (2019) → $4.99/mo or $30/yr (Jan 2020) → $7.49 / $29.99 / $99.99 lifetime (2023); pricing-model union 212 (9.73%, mean 2.92); Canada's CAD $39.99 / $129.99 sharpens it ('Are you out of your mind???').")
ext("C065", " Report 46: payers (97) rate 3.95 vs 4.35, 1.7× as likely to leave 1★ and 2.9× 2★; 21 of 97 (21.6%) hit a defect after paying; every payer at 1★ (12) is a delivery or billing failure, none a design objection.")
ext("C069", " Report 46: sounds / stronger completion feedback requested by 5; a December 2022 completion animation was rejected ('please remove the new animation whenever u log a day it's so annoying'; 'Special FX update unnecessary… I'll not renew').")
ext("C073", " Report 46: cannot reorder habits (10, mean 4.10); a limited history view (9).")
ext("C075", " Report 46: onboarding confusion 19 (mean 3.95); the skip-symbol legend is missed at first run and cannot be found again ('I missed the intro and can't find it again').")
ext("C080", " Report 46: dark mode paywalled (2020, June 2024) — the report's #7 fix returns it to the free tier.")
ext("C085", " Report 46: 'Completely functional without paying! No ads!' (chronic pain); no ads praised by 10 (4.90); no account needed by 2024.")
ext("C089", " Report 46: a Black Friday €15 price; a December discount honoured after it expired ('Joan still hooked me up with the discounted subscription', 5★).")
ext("C092", " Report 46: regional price complaints 8 (all non-US — Turkey ₺179 / ₺30 a month, Saudi 109 SAR, Vietnam, Latin America, Israel cannot buy online, Kazakhstan) while Russia calls its price fair; the report's E2 is regional lifetime pricing.")
ext("C093", " Report 46: the upsell twin of the rating prompt — 'everytiime I try to add a new habit or move between screens the upgrade to premium screen appears and has to be x multiple times' (4, mean 1.50); a paywall on first open for some ('Take a subscription straight away or look at the start screen. That's all').")
ext("C094", " Report 46: the largest self-inflicted problem in a 2,178-review corpus — an in-app rating prompt with no 'don't ask again' (50 complaints, mean 3.22, 10 one-stars; 'App asks me to review 4 times in 10 minutes. I haven't even setup 2 habits yet. Only option is Not now… Think twice before adding dark patterns'; 'you keep asking me for a review? → I'm punishing you'), asked during setup, of subscribers, and across platforms, 'fixed' in June 2023 yet live in August 2026; it capped 11 of 143 three-star ratings; the report's #1 fix: never in the first week, never twice per version, never after a rating or dismissal, never for subscribers.")
ext("C095", " Report 46: 'not ticks to check off but areas that fill with beautiful colours — so I don't feel stressed about not managing something'; 'a triangle in that space… feels like neutral data instead of a personal failing'.")
ext("C101", " Report 46: the colour saturation itself is the reward — no badges needed; a gentler decay on a miss is asked for by 6 (mean 4.67) but must be tested against the neurodivergent segment.")
ext("C104", " Report 46: dark mode 'moved behind a paywall' in a June 2024 update ('Immediate deletion').")
ext("C109", " Report 46: two charged on day one of a 7-day trial ('Offerred 7 day trial, but I got charged the same day'); after a trial ends the extra habits are locked, not archivable ('I can't delete them… it falsifies the statistics') — the report's #8: let the user choose which 3 stay and archive the rest.")
ext("C112", " Report 46: six cancellations threatened or described, one on the last day of the trial after a developer reply; 'I just cancelled the subscription. That's $29 down the drain'.")
ext("C116", " Report 46: a free Learn tab (articles, videos, James Clear material) and 7-day e-mail course were praised as 'like a life changing book' by early users (107, mean 4.82) and faded 11.02% → 3.30% as the audience turned mobile; English-only; the report's E6 resurfaces it after day 14.")
ext("C133", " Report 46: the report's #9 is 3 → 4 free habits — the smallest change that fixes the widget defect and answers the counter-offer without touching the habit-science defence.")
ext("C141", " Report 46: landscape / wider view requested by 4 ('The rating will change when there's a landscape mode').")
ext("C143", " Report 46: several completions per day requested by 12.")
ext("C147", " Report 46: 'By the time you discover that you can only track 3 habits with the free version, you've already spent 20 minutes or more setting it up' (16 votes); 'every tab I open to poke around is locked'-style evaluation failures; a 30-day full trial asked for.")
ext("C150", " Report 46: 'It's asking whether I like the app just as I downloaded it!'; 'every other time I marked a habit as complete the app popped up a window asking me to rate it'.")
ext("C153", " Report 46: the report's #2 is a per-habit change history with one-tap 'undo last 7 days' and conflict resolution that never deletes a completed mark.")
ext("C155", " Report 46: an unrequested Dec 2022 completion animation cost a subscriber ('I'll not renew').")
ext("C157", " Report 46: the skip mark is why perfectionists stay — 'you don't want to break a streak, so you keep going' with 'no punishment other than a break in the color gradient'; rule 17: do not remove or harden the forgiving skip.")
ext("C170", " Report 46 (counter-signal): none; the grid's day boundary is not raised.")
ext("C171", " Report 46: accessibility requests 8 (font size, VoiceOver, reading needs — 'unique reading needs' from a dyslexic 5★); a VoiceOver regression on iOS 15 (IT).")
ext("C172", " Report 46: journal / per-day notes shipped Dec 2023 (praised 12, mean 4.67) after 9 requests.")
ext("C175", " Report 46: 'The new IOS update has wiped all of my historical and tracking data' (GB, 1★, Sep 2022); a Sep 2020 'won't open after the update' cluster of six reviews in three days across five storefronts.")
ext("C177", " Report 46: three concurrent premium SKUs (ED Premium Monthly, Everyday Premium Year, ED Full Year Access) beside a lifetime; a web price cheaper than in-app ('only $12 a year on the website, more in the app').")
ext("C178", " Report 46: 'habitica but without the stupid game mechanics'; no gamification praised (3, all 5★).")
ext("C181", " Report 46: 'free forever' on the listing and website with a 3-habit tier is the angriest cluster (27, mean 1.85 — 'Potential but FREE FOREVER description is misleading'; 'IS NOT A FREE APP, it just has a free try-it-and-see mode'; 'not a one [screenshot] shows what the free version looks like'); the report's #5: remove 'free forever' and add a screenshot of the free tier.")
ext("C186", " Report 46 (fear of it): 'Among apps that charge ¥30 for lifetime, this one wants ¥328 — I really don't dare buy it, in case it disappears'; five Chinese reviews hesitate for fear the app will 跑路.")
ext("C188", " Report 46: free users cannot check off a habit offline ('ticking off habits while offline are locked behind a paywall', 7, mean 2.14) — the mechanism behind China's 'offline mode while online' cluster (16 of 17 Chinese, Sep 2019 – Apr 2020, consistent with the backend being unreachable from the mainland); the report's #14 allows offline check-off in the free tier.")
ext("C218", " Report 46: 'Every picture shows a bunch of colorful habit trackers, not a one shows what the free version looks like' — a screenshot of the actual 3-habit free view is the fix.")
ext("C222", " Report 46: 66 reviewers (3.03%, mean 4.92) defend a 3-habit cap on habit-science grounds ('shouldn't be tracking more than three in the first place'; 'the limit is beneficial since it kept me from piling expectations onto myself') while the counter-offer is 4–7 — the defensible cap is disclosed and framed as focus.")
ext("C231", " Report 46: the same product is loved and disputed differently per storefront — Germany 3.95 with every monetisation theme 2–4× global, Russia 4.43 calling the price fair, China objecting to the payment shape not the cap, India negotiating, Turkey regional price, Spain the harshest cap objection (mean 2.00) beside Catalan praise.")
ext("C234", " Report 46: statistics free; richer stats requested by 11.")
ext("C236", " Report 46: the free tier cannot fill the product's own 4-row widget ('it leaves the 4th row blank… it bothers me so much'; 'makes many widgets appear broken as they tend to have a multiple of 4 rows').")
ext("C240", " Report 46: a rating prompt 'every other time I marked a habit as complete'; a Dec 2022 completion animation on every log ('so annoying').")
ext("C246", " Report 46: zero ads; no ads praised by 10 (mean 4.90).")
ext("C253", " Report 46: a daily e-mail at exactly 12 with a new sender address each time (3, mean 1.67, 2020–23) was made switchable ('You can turn them off if you don't like it').")
ext("C255", " Report 46: two German reviewers could not use the app because they do not read English (2020, Dec 2023) although German is listed.")
ext("C256", " Report 46: 'missed' distinct from 'not recorded' requested by 6 (mean 4.67) — and the skip semantics confuse 19.")
ext("C257", " Report 46 (contrast): reminders are free; the paid gates are habit count, dark mode, offline use and sync.")
ext("C250", " Report 46: 'An email at exactly 12 every day is really intrusive, and I can't find how to cancel'; 'the sender has a new address for each message' (1★).")

